    19→function parseImageDimensions(buf: Buffer): { width: number; height: number } {
    20→  // PNG: bytes 0-7 = signature, 8-15 = IHDR length+type, 16-19 = width, 20-23 = height
    21→  if (buf.length >= 24 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
    22→    return {
    23→      width: buf.readUInt32BE(16),
    24→      height: buf.readUInt32BE(20),
    25→    };
    26→  }
    27→  // JPEG: scan for SOF0/SOF2 markers (0xFF 0xC0 or 0xFF 0xC2)
    28→  if (buf.length >= 2 && buf[0] === 0xff && buf[1] === 0xd8) {
    29→    let i = 2;
    30→    while (i < buf.length - 9) {
    31→      if (buf[i] !== 0xff) { i++; continue; }
    32→      const marker = buf[i + 1];
    33→      if (marker === 0xc0 || marker === 0xc2) {
    34→        return {
    35→          height: buf.readUInt16BE(i + 5),
    36→          width: buf.readUInt16BE(i + 7),
    37→        };
    38→      }
    39→      // Skip to next marker
    40→      const segLen = buf.readUInt16BE(i + 2);
    41→      i += 2 + segLen;
    42→    }
    43→  }
    44→  // WebP: RIFF header, bytes 24-27 = width (LE 14 bits), 26-29 = height (LE 14 bits) for VP8
    45→  // Simplified: just return 0 for unsupported formats
    46→  return { width: 0, height: 0 };
    47→}
