     1→import { describe, it, expect, beforeEach, afterEach } from "bun:test";
     2→import { startWsTestServer, type WsTestServer } from "../helpers";
     3→import { createAdventure } from "../../src/db/adventures";
     4→import { createImageRecord } from "../../src/db/images";
     5→import { getTokensByAdventure } from "../../src/db/tokens";
     6→
     7→// ---- WebSocket test helpers ----
     8→
     9→function connectWS(wsUrl: string, params: Record<string, string>): Promise<WebSocket> {
    10→  const url = new URL(`${wsUrl}/ws`);
    11→  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
    12→  return new Promise((resolve, reject) => {
    13→    const ws = new WebSocket(url.toString());
    14→    const timer = setTimeout(() => {
    15→      ws.close();
    16→      reject(new Error("WebSocket connect timeout"));
    17→    }, 5000);
    18→    ws.onopen = () => {
    19→      clearTimeout(timer);
    20→      resolve(ws);
    21→    };
    22→    ws.onerror = () => {
    23→      clearTimeout(timer);
    24→      reject(new Error("WebSocket connection error"));
    25→    };
    26→  });
    27→}
    28→
    29→function waitForMessage(ws: WebSocket, type: string, timeout = 3000): Promise<any> {
    30→  return new Promise((resolve, reject) => {
    31→    const timer = setTimeout(() => {
    32→      ws.removeEventListener("message", handler);
    33→      reject(new Error(`Timeout waiting for message type: ${type}`));
    34→    }, timeout);
    35→    const handler = (event: MessageEvent) => {
    36→      const msg = JSON.parse(event.data as string);
    37→      if (msg.type === type) {
    38→        clearTimeout(timer);
    39→        ws.removeEventListener("message", handler);
    40→        resolve(msg);
    41→      }
    42→    };
    43→    ws.addEventListener("message", handler);
    44→  });
    45→}
    46→
    47→function closeWs(ws: WebSocket): Promise<void> {
    48→  return new Promise((resolve) => {
    49→    if (ws.readyState === WebSocket.CLOSED) {
    50→      resolve();
    51→      return;
    52→    }
    53→    ws.onclose = () => resolve();
    54→    ws.close();
    55→  });
    56→}
    57→
    58→// ---- Tests ----
    59→
    60→describe("WebSocket handler", () => {
    61→  let ts: WsTestServer;
    62→  let adventureId: string;
    63→  let gmPassword: string;
    64→  let playerLink: string;
    65→  let imageId: string;
    66→  const openSockets: WebSocket[] = [];
    67→
    68→  function track(ws: WebSocket): WebSocket {
    69→    openSockets.push(ws);
    70→    return ws;
    71→  }
    72→
    73→  beforeEach(() => {
    74→    ts = startWsTestServer();
    75→    const adventure = createAdventure(ts.db, { name: "Test Adventure", gmPassword: "secret" });
    76→    adventureId = adventure.id;
    77→    gmPassword = adventure.gm_password;
    78→    playerLink = adventure.player_link;
    79→    const image = createImageRecord(ts.db, {
    80→      adventureId,
    81→      filename: "test.png",
    82→      originalName: "test.png",
    83→      width: 100,
    84→      height: 100,
    85→    });
    86→    imageId = image.id;
    87→  });
    88→
    89→  afterEach(async () => {
    90→    for (const ws of openSockets) {
    91→      if (ws.readyState !== WebSocket.CLOSED) ws.close();
    92→    }
    93→    openSockets.length = 0;
    94→    // Small delay to let close handlers fire before stopping server
    95→    await new Promise((r) => setTimeout(r, 50));
    96→    ts.stop();
    97→  });
    98→
    99→  it("GM connects with correct password → receives joined", async () => {
   100→    const ws = track(
   101→      await connectWS(ts.wsUrl, { adventureId, role: "gm", password: gmPassword })
   102→    );
   103→    const msg = await waitForMessage(ws, "joined");
   104→    expect(msg.adventure.id).toBe(adventureId);
   105→    expect(msg.adventure.name).toBe("Test Adventure");
   106→    expect(Array.isArray(msg.tokens)).toBe(true);
   107→  });
   108→
   109→  it("GM connects with wrong password → HTTP 401", async () => {
   110→    const url = new URL(`${ts.wsUrl}/ws`.replace("ws://", "http://"));
   111→    url.searchParams.set("adventureId", adventureId);
   112→    url.searchParams.set("role", "gm");
   113→    url.searchParams.set("password", "wrong");
   114→    const res = await fetch(url.toString());
   115→    expect(res.status).toBe(401);
   116→  });
   117→
   118→  it("Player connects with valid player link → receives joined with token", async () => {
   119→    const ws = track(
   120→      await connectWS(ts.wsUrl, {
   121→        adventureId,
   122→        role: "player",
   123→        playerLink,
   124→        playerName: "Alice",
   125→        playerColor: "#ff0000",
   126→      })
   127→    );
   128→    const msg = await waitForMessage(ws, "joined");
   129→    expect(msg.adventure.id).toBe(adventureId);
   130→    expect(msg.tokens.length).toBeGreaterThan(0);
   131→    const token = msg.tokens.find((t: any) => t.name === "Alice");
   132→    expect(token).toBeDefined();
   133→    expect(token.color).toBe("#ff0000");
   134→  });
   135→
   136→  it("Player connects with invalid player link → HTTP 401", async () => {
   137→    const url = new URL(`${ts.wsUrl}/ws`.replace("ws://", "http://"));
   138→    url.searchParams.set("adventureId", adventureId);
   139→    url.searchParams.set("role", "player");
   140→    url.searchParams.set("playerLink", "badlink");
   141→    url.searchParams.set("playerName", "Alice");
   142→    url.searchParams.set("playerColor", "#ff0000");
   143→    const res = await fetch(url.toString());
   144→    expect(res.status).toBe(401);
   145→  });
   146→
   147→  it("Player connects → other clients receive player:joined and token:added", async () => {
   148→    const gm = track(
   149→      await connectWS(ts.wsUrl, { adventureId, role: "gm", password: gmPassword })
   150→    );
   151→    await waitForMessage(gm, "joined");
   152→
   153→    // Connect player while listening for notifications on gm
   154→    const playerJoinedPromise = waitForMessage(gm, "player:joined");
   155→    const tokenAddedPromise = waitForMessage(gm, "token:added");
   156→
   157→    const player = track(
   158→      await connectWS(ts.wsUrl, {
   159→        adventureId,
   160→        role: "player",
   161→        playerLink,
   162→        playerName: "Bob",
   163→        playerColor: "#00ff00",
   164→      })
   165→    );
   166→    await waitForMessage(player, "joined");
   167→
   168→    const playerJoined = await playerJoinedPromise;
   169→    expect(playerJoined.playerName).toBe("Bob");
   170→    expect(playerJoined.playerColor).toBe("#00ff00");
